func (v AgentValue) Equal(o attr.Value) bool {
	other, ok := o.(AgentValue)

	if !ok {
		return false
	}

	if v.state != other.state {
		return false
	}

	if v.state != attr.ValueStateKnown {
		return true
	}

	if !v.AgentId.Equal(other.AgentId) {
		return false
	}

	if !v.AllowedCollections.Equal(other.AllowedCollections) {
		return false
	}

	if !v.AllowedTools.Equal(other.AllowedTools) {
		return false
	}

	if !v.AssignedSkills.Equal(other.AssignedSkills) {
		return false
	}

	if !v.CreatedAt.Equal(other.CreatedAt) {
		return false
	}

	if !v.CreatedBy.Equal(other.CreatedBy) {
		return false
	}

	if !v.Description.Equal(other.Description) {
		return false
	}

	if !v.Group.Equal(other.Group) {
		return false
	}

	if !v.GuardrailPreset.Equal(other.GuardrailPreset) {
		return false
	}

	if !v.HasOverlay.Equal(other.HasOverlay) {
		return false
	}

	if !v.IsGlobal.Equal(other.IsGlobal) {
		return false
	}

	if !v.LongContext.Equal(other.LongContext) {
		return false
	}

	if !v.MaxTokens.Equal(other.MaxTokens) {
		return false
	}

	if !v.ModelId.Equal(other.ModelId) {
		return false
	}

	if !v.Name.Equal(other.Name) {
		return false
	}

	if !v.SystemPrompt.Equal(other.SystemPrompt) {
		return false
	}

	if !v.Temperature.Equal(other.Temperature) {
		return false
	}

	if !v.UpdatedAt.Equal(other.UpdatedAt) {
		return false
	}

	return true
}

